    answer: "\u0A95\u0ABE\u0AB0\u0AA3 \u0A95\u0AC7 \u0AB0\u0AB8\u0ACD\u0AA4\u0ABE \u0A85\u0AA8\u0AC7 \u0A9F\u0ABE\u0AAF\u0AB0 \u0AB5\u0A9A\u0ACD\u0A9A\u0AC7 \u0AB5\u0ABF\u0AB0\u0AC1\u0AA6\u0ACD\u0AA7 \u0AA6\u0ABF\u0AB6\u0ABE\u0AAE\u0ABE\u0A82 \u0A98\u0AB0\u0ACD\u0AB7\u0AA3 \u0AAC\u0AB3 (Frictional Force) \u0AB2\u0ABE\u0A97\u0AC7 \u0A9B\u0AC7, \u0A9C\u0AC7 \u0AB8\u0ABE\u0A87\u0A95\u0AB2\u0AA8\u0AC0 \u0A97\u0AA4\u0ABF\u0AA8\u0AC7 \u0A85\u0AB5\u0AB0\u0ACB\u0AA7\u0AC7 \u0A9B\u0AC7!",
    points: [
      "\u0AE7. \u0AAA\u0ACD\u0AB0\u0AA5\u0AAE \u0AA8\u0ABF\u0AAF\u0AAE: \u0AAC\u0ABE\u0AB9\u0ACD\u0AAF \u0AAC\u0AB3 \u0AB5\u0A97\u0AB0 \u0AAA\u0AA6\u0ABE\u0AB0\u0ACD\u0AA5 \u0AAA\u0ACB\u0AA4\u0ABE\u0AA8\u0AC0 \u0AB8\u0ACD\u0AA5\u0ABF\u0AA4\u0ABF \u0AAC\u0AA6\u0AB2\u0AA4\u0ACB \u0AA8\u0AA5\u0AC0 (\u0A9C\u0AA1\u0AA4\u0ACD\u0AB5).",
      "\u0AE8. \u0AA6\u0ACD\u0AB5\u0ABF\u0AA4\u0AC0\u0AAF \u0AA8\u0ABF\u0AAF\u0AAE: \u0AAC\u0AB3 = \u0AA6\u0AB3 \xD7 \u0AAA\u0ACD\u0AB0\u0AB5\u0AC7\u0A97 (F = ma); \u0AAC\u0AB3 \u0AAE\u0ABE\u0AAA\u0AB5\u0ABE\u0AA8\u0AC1\u0A82 \u0A97\u0ABE\u0AA3\u0ABF\u0AA4\u0ABF\u0A95 \u0AB8\u0AC2\u0AA4\u0ACD\u0AB0 \u0A86\u0AAA\u0AC7 \u0A9B\u0AC7.",
      "\u0AE9. \u0AA4\u0AC3\u0AA4\u0AC0\u0AAF \u0AA8\u0ABF\u0AAF\u0AAE: \u0AA6\u0AB0\u0AC7\u0A95 \u0A95\u0ACD\u0AB0\u0ABF\u0AAF\u0ABE\u0AAC\u0AB3\u0AA8\u0AC0 \u0AB8\u0ABE\u0AAE\u0AC7 \u0AB8\u0AAE\u0ABE\u0AA8 \u0A85\u0AA8\u0AC7 \u0AB5\u0ABF\u0AB0\u0AC1\u0AA6\u0ACD\u0AA7 \u0AA6\u0ABF\u0AB6\u0ABE\u0AA8\u0AC1\u0A82 \u0AAA\u0ACD\u0AB0\u0AA4\u0ACD\u0AAF\u0ABE\u0A98\u0ABE\u0AA4\u0AC0 \u0AAC\u0AB3 \u0AB9\u0ACB\u0AAF \u0A9B\u0AC7.",
      "\u0AEA. \u0AB8\u0AC0\u0A9F\u0AAC\u0AC7\u0AB2\u0ACD\u0A9F, \u0AB0\u0ACB\u0A95\u0AC7\u0A9F \u0A85\u0AA8\u0AC7 \u0A95\u0ACD\u0AB0\u0ABF\u0A95\u0AC7\u0A9F \u0A95\u0AC7\u0A9A \u0AA8\u0ACD\u0AAF\u0AC2\u0A9F\u0AA8\u0AA8\u0ABE \u0A97\u0AA4\u0ABF\u0AA8\u0ABE \u0AA8\u0ABF\u0AAF\u0AAE\u0ACB \u0AAA\u0AB0 \u0A86\u0AA7\u0ABE\u0AB0\u0ABF\u0AA4 \u0A9B\u0AC7."
    ]
